const main=document.querySelector('main');
const A='assets/';
const arrow='<span aria-hidden="true">↗</span>';
const image=(name,alt,cls='',eager=false)=>`<img src="${A+name}" alt="${alt}" class="${cls}" ${eager?'fetchpriority="high"':'loading="lazy"'} decoding="async">`;
const link=(href,label,cls='text-link')=>`<a href="${href}" class="${cls}">${label}${arrow}</a>`;
const ext=(href,label,cls='text-link')=>`<a href="${href}" class="${cls}" target="_blank" rel="noopener noreferrer">${label}${arrow}</a>`;
const getBrand=id=>brands.find(b=>b.id===id),getStory=id=>stories.find(s=>s.id===id);
const crumbs=label=>`<div class="crumbs"><a href="#/">TOP</a><span>/</span>${label}</div>`;
const badge='<span class="demo-badge">DEMO / 編集サンプル</span>';
const sourceNote=(url,label)=>`<p class="source-note">公開情報をもとに再構成したデモ記事です。<a href="${url}" target="_blank" rel="noopener noreferrer">出典：${label} ↗</a></p>`;
let activeBrand='tsukada',answers=[],quizStep=0;
function heading(kicker,title,more=''){return `<div class="section-heading reveal"><div><div class="eyebrow">${kicker}</div><h2>${title}</h2></div>${more}</div>`;}
function storyCard(s){return `<a class="story-card reveal" href="#/story/${s.id}"><div class="card-image">${image(s.image,s.alt)}<span class="card-no">${s.no}</span>${s.id==='people'?'<span class="image-note">架空人物 / AI生成</span>':''}</div><div class="card-meta">${pillars[s.category]}<span>DEMO STORY</span></div><h3>${s.title}</h3><span class="card-read">READ STORY ${arrow}</span></a>`;}
function brandPanel(id){const b=getBrand(id);return `<a class="brand-photo" href="#/brand/${b.id}">${image(b.image,b.alt)}<span class="photo-label">${b.en} / ${b.category}</span></a><div class="brand-caption"><p>${b.tag}</p>${link('#/brand/'+b.id,'このブランドの世界へ')}</div>`;}
function actions(){return `<section class="actions wrap">${heading('YOUR NEXT STEP','気になった、その先へ。')}<div class="action-grid">${link('#/stores','食べに行く・店舗を探す')}${link('#/brands','ブランドをもっと知る')}${ext('https://career-recruit.ap-holdings.jp/','一緒に働く（公式採用）')}${ext('https://ap-holdings.jp/contact/','一緒につくる（公式窓口）')}</div></section>`;}
function home(){activeBrand='tsukada';return `
<section class="hero"><div class="hero-photo-wrap">${image('flame.png','塚田農場の地鶏を焼き上げる炭火の炎','hero-photo',true)}</div><div class="hero-top"><span>AP HOLDINGS / BRAND MEDIA</span><span>PROPOSAL DEMO — 2026</span></div><div class="hero-title"><p>THERE IS MORE BEHIND EVERY BITE.</p><h1><span>食の、</span><span>その先へ。</span></h1></div><div class="hero-bottom"><p>一皿の向こうに、まだ知らない世界がある。<br>産地、食、店、人。そして、未来。</p><a class="hero-link" href="#/story/jidori">一羽の地鶏から、旅をはじめる ${arrow}</a></div><div class="hero-side">FOOD CREATIVE FIRM.</div><a class="hero-scroll" href="#food-journey" data-scroll="food-journey" aria-label="食の旅へスクロール">SCROLL TO TASTE <span>↓</span></a></section>
<div class="ticker" aria-hidden="true"><div>FROM THE LAND. TO THE TABLE. BEYOND THE PLATE. FROM THE LAND. TO THE TABLE. BEYOND THE PLATE.</div></div>
<section class="intro wrap"><span class="eyebrow reveal">WE ARE A FOOD CREATIVE FIRM.</span><div class="intro-grid"><h2 class="reveal">おいしい、で<br>終わらない。<br><span>おいしい、から<br>広がっていく。</span></h2><div class="intro-body reveal"><p>一皿をたどれば、育てる人がいる。<br>その土地があり、料理人の工夫があり、<br>集う人の笑顔がある。</p><p>APホールディングスが向き合うのは、<br>食を取り巻く世界そのもの。</p>${link('#/about','食のあるべき姿を追求する')}</div></div></section>
<section id="food-journey" class="journey"><div class="journey-sticky"><div class="journey-images">${[['flame.png','塚田農場の炭火調理'],['jidori.png','炭火で焼き上げた地鶏'],['farm.png','塚田農場の契約農家の皆さん']].map((x,i)=>image(x[0],x[1],`journey-image ${i===0?'active':''}`)).join('')}</div><div class="journey-overlay"><div class="eyebrow">ONE PLATE. MANY STORIES.</div><div class="journey-copy"><span class="journey-number">01</span><h2>炎の先に、<br>つくる人の手。</h2><p>炭と炎を見極める。その一瞬に、料理人の仕事がある。</p></div><div class="journey-nav" aria-label="一皿の背景をたどる">${['火を入れる','一皿になる','産地へつながる'].map((x,i)=>`<button data-journey="${i}" aria-pressed="${i===0}"><span>0${i+1}</span>${x}</button>`).join('')}</div><div class="journey-progress"><span></span></div></div></div></section>
<section class="worlds wrap"><div class="worlds-lead reveal"><span class="eyebrow">FIVE PERSPECTIVES, ONE WORLD.</span><h2>入口は、ひとつじゃない。</h2></div><div class="world-links">${pillars.map((p,i)=>`<a class="reveal" href="#/stories/${i}"><small>0${i+1}</small>${p}<span>↗</span></a>`).join('')}</div><p class="small-note">「つくる」は、このメディアの編集テーマです。</p></section>
<section class="feature wrap"><div class="feature-label reveal"><span>THE FEATURE</span><span>VOL. 01</span></div><a class="feature-image reveal" href="#/story/jidori">${image('jidori.png','炭火をまとった地鶏の一皿')}<span class="round-link" aria-hidden="true">↗</span></a><div class="feature-copy reveal"><div><span class="eyebrow">食をつくる × 産地とつくる</span><h2><a href="#/story/jidori">一羽の地鶏が、<br>塚田農場の一皿になるまで。</a></h2></div><div><p>その香ばしさの向こう側に、<br>育てる人の時間がある。<br>一皿からたどる、生販直結の物語。</p>${link('#/story/jidori','ストーリーを読む')}</div></div></section>
<section class="brand-section wrap">${heading('EXPLORE OUR BRANDS','ひとつの想い。<br>いくつもの、おいしい。',link('#/brands','ブランドをもっと知る'))}<div class="brand-explorer"><div class="brand-selector" role="tablist" aria-label="ブランドを選ぶ">${brands.map((b,i)=>`<button role="tab" id="brand-tab-${b.id}" aria-controls="brand-panel" aria-selected="${i===0}" tabindex="${i===0?0:-1}" data-brand="${b.id}"><small>0${i+1} / ${b.category}</small><strong>${b.name}</strong><span>↗</span></button>`).join('')}</div><div id="brand-panel" role="tabpanel" aria-labelledby="brand-tab-tsukada">${brandPanel('tsukada')}</div></div></section>
<section class="origin-section"><div class="origin-image">${image('farm.png','塚田農場の契約農家の皆さんと、その背景に広がる緑')}</div><div class="origin-copy reveal"><div class="eyebrow">BEYOND THE TABLE / ORIGINS</div><h2>店の向こうに、<br>この風景がある。</h2><p>食材を知ることは、土地を知ること。<br>つくる人を知ること。<br>宮崎の地鶏から、各地の海へ。<br>おいしさの原点を訪ねて。</p>${link('#/region','産地の物語へ')}<small>写真：塚田農場公式サイトより</small></div></section>
<section class="people-section wrap">${heading('THE PEOPLE BEHIND THE FOOD','この食を、<br>つくっている人たち。',link('#/people','人から、食を知る'))}${peopleFeature()}</section>
<section class="stories-section wrap">${heading('LATEST STORIES','食の世界は、今日も広がる。',link('#/stories','すべてのストーリー'))}<div class="story-grid">${[stories[1],stories[2],stories[5]].map(storyCard).join('')}</div></section>
<section class="diagnosis-banner"><div class="reveal"><div class="eyebrow">FIND YOUR NEXT TABLE.</div><h2>今のあなたは、<br>どんな「おいしい」気分？</h2><p>3つの質問から、今日行きたいAPブランドに出会う。</p>${link('#/diagnosis','あなたに合うブランドを見つける','solid-link')}</div><div class="diagnosis-type" aria-hidden="true">GOOD<br>FOOD.<br><em>YOUR</em><br>MOOD.</div><span class="quiz-stamp">3 QUESTIONS<br>約30秒</span></section>
<section class="future-section wrap"><span class="eyebrow">THE NEXT CHAPTER</span><h2 class="reveal">食文化の未来も。<br>飲食人の未来も。<br>生産地の未来も。</h2><div class="reveal"><p>つくる人、届ける人、楽しむ人。<br>そのすべてに、次の可能性を。<br>食の未来を広げていく、FOOD CREATIVE FIRM。</p>${link('#/story/future','未来につながるストーリー')}</div></section>${actions()}`;}
function peopleFeature(){return `<a class="people-feature reveal" href="#/person/naoto"><div class="people-portrait">${image('fictional-chef.png','架空人物・高橋直人のAI生成画像')}<span>DEMO / 架空人物・AI生成画像</span></div><div class="people-quote"><span class="eyebrow">PEOPLE 01 / 料理をつくる人</span><h3>「おいしい」の理由を、<br>自分の言葉で<br>伝えられる料理人に。</h3><p>高橋 直人 <small>NAOTO TAKAHASHI</small></p><span class="small-note">塚田農場の料理人を想定した、架空のストーリー。</span><span class="text-link">この人の物語を読む ${arrow}</span></div></a>`;}
function related(b,omit=''){const entries=[['STORY',getStory(b.story).title,'#/story/'+b.story,getStory(b.story).image],['FOOD',b.food,'#/food/'+b.id,b.image],['ORIGIN',b.region==='sea'?'全国の海と、漁師の仕事':'宮崎・地鶏を育てる土地','#/region/'+b.region,b.region==='sea'?'fish.jpg':'chickens.png'],['BRAND',b.name,'#/brand/'+b.id,b.image],['PEOPLE','料理人を知る（架空人物サンプル）','#/person/naoto','fictional-chef.png']].filter(e=>e[0]!==omit);return `<section class="related wrap">${heading('EVERYTHING IS CONNECTED.','この物語の、つづきへ。')}<div class="related-grid">${entries.map(e=>`<a href="${e[2]}">${image(e[3],e[1])}<small>${e[0]}</small><h3>${e[1]}</h3>${arrow}</a>`).join('')}</div></section>`;}
function storiesPage(filter='all'){const visible=filter==='all'?stories:stories.filter(s=>String(s.category)===filter);return `<div class="wrap">${crumbs('STORIES')}<div class="page-head"><div class="eyebrow">STORIES</div><h1>知るほどに、<br>食はおもしろくなる。</h1><p>食、産地、店、人、未来。ひとつの世界を、いろいろな入口から。</p></div><div class="filters" aria-label="ストーリーのテーマ">${['all',...pillars.map((_,i)=>String(i))].map((id,i)=>`<a href="#/stories${id==='all'?'':'/'+id}" ${filter===id?'aria-current="true"':''}>${i===0?'すべて':pillars[i-1]}</a>`).join('')}</div><p class="result-count">${String(visible.length).padStart(2,'0')} STORIES <span>記事はすべてデモ用の編集サンプルです。</span></p><div class="story-grid story-list">${visible.map(storyCard).join('')}</div></div>${actions()}`;}
function article(id){const s=getStory(id);if(!s)return notFound();const b=getBrand(s.brand);return `<article><div class="wrap">${crumbs(`<a href="#/stories">STORIES</a><span>/</span>${pillars[s.category]}`)}<div class="article-head"><div class="eyebrow">${pillars[s.category]} / STORY ${s.no}</div><h1>${s.title}</h1><p>${s.sub}</p>${badge}${id==='people'?'<p class="small-note">人物・発言・経歴は架空。顔写真はAI生成画像です。</p>':''}</div><figure class="article-hero">${image(s.image,s.alt,'',true)}</figure></div><div class="article-body"><p class="article-intro">${s.intro}</p><div class="article-index"><small>この物語をたどる</small>${s.sections.map((a,i)=>`<a href="#chapter-${i}" data-scroll="chapter-${i}">${a[0]} ↓</a>`).join('')}</div>${s.sections.map((a,i)=>`<section id="chapter-${i}"><h2>${a[0]}</h2><p>${a[1]}</p>${a[2]?`<figure>${image(a[2],a[0])}<figcaption>公式公開写真 / 詳細は出典ページへ</figcaption></figure>`:''}</section>`).join('')}<p class="article-ending">${s.ending}</p>${sourceNote(b.site,b.name+'公式サイト')}${id==='jidori'?sourceNote('https://ap-holdings.jp/business-model/','APホールディングス｜ビジネスモデル'):''}${link('#/food/'+b.id,'この物語の料理を知る','solid-link')}</div></article>${related(b,'STORY')}${storeCta(b)}`;}
function brandsPage(){return `<div class="wrap">${crumbs('BRANDS')}<div class="page-head"><div class="eyebrow">A WORLD OF FLAVORS</div><h1>今日は、<br>どの世界を味わおう。</h1><p>地鶏も、魚も、一本の焼鳥も。同じ想いから広がる、異なる食の時間。</p></div><div class="brand-catalog">${brands.map((b,i)=>`<a href="#/brand/${b.id}" class="brand-catalog-item reveal"><div>${image(b.image,b.alt)}<span>0${i+1}</span></div><div><small>${b.en} / ${b.category}</small><h2>${b.name}</h2><p>${b.tag}</p><span class="text-link">このブランドの世界へ ${arrow}</span></div></a>`).join('')}</div><div class="more-brands"><h2>APの世界は、まだまだ広い。</h2><p>北海道シントク町 塚田農場 ／ なきざかな ／ 芝浦食肉 ／ しゃぶしゃぶつかだ ／ 裏の山の木の子 ほか</p>${ext('https://ap-holdings.jp/brand-and-business/','全ブランドを公式サイトで見る')}</div></div>${actions()}`;}
function brandPage(id){const b=getBrand(id);if(!b)return notFound();return `<div class="wrap">${crumbs(`<a href="#/brands">BRANDS</a><span>/</span>${b.name}`)}</div><section class="brand-detail-hero">${image(b.image,b.alt,'',true)}<div><span class="eyebrow">${b.en}</span><h1>${b.name}</h1><p>${b.tag}</p></div></section><div class="detail-intro wrap"><span class="eyebrow">THE BRAND</span><h2>${b.intro}</h2><p>${b.origin}</p>${ext(b.site,'ブランド公式サイト')}</div><section class="brand-food wrap"><div>${image(b.id==='yakitori'?'yakitori-c.jpg':b.image,b.food)}</div><div><div class="eyebrow">SIGNATURE / 代表的な料理</div><h2>${b.food}</h2><p>${b.foodText}</p>${link('#/food/'+b.id,'料理から、背景を知る')}</div></section><section class="brand-origin wrap"><span class="eyebrow">FROM THE SOURCE</span><h2>${b.region==='sea'?'全国の海と、つながる。':'宮崎の大地から、この一皿へ。'}</h2><p>${b.region==='sea'?'漁師や漁協、産地市場。その仕事から、食卓のおいしさは始まっています。':'地鶏を育てる時間と、つくる人の仕事。ブランドの原点をたどります。'}</p>${link('#/region/'+b.region,'産地・生産者の物語へ')}</section>${related(b,'BRAND')}${storeCta(b)}<div class="secondary-career wrap">${ext('https://career-recruit.ap-holdings.jp/','この食の世界で働くことに興味がある方へ')}</div>`;}
function foodPage(id){const b=getBrand(id);if(!b)return notFound();return `<div class="wrap">${crumbs('FOOD')}<div class="food-detail"><div>${image(b.image,b.food,'',true)}</div><div><div class="eyebrow">FOOD / ${b.name}</div><h1>${b.food}</h1><p>${b.foodText}</p><div class="food-info"><span>ブランド</span><a href="#/brand/${b.id}">${b.name} ↗</a><span>おいしさの背景</span><a href="#/region/${b.region}">${b.region==='sea'?'全国の漁師・漁協とのつながり':'宮崎の地鶏と、生産者の仕事'} ↗</a></div><p class="small-note">メニューの内容・提供状況は店舗や時期により異なります。</p>${link('#/region/'+b.region,'この一皿の産地へ','solid-link')}</div></div></div>${related(b,'FOOD')}${storeCta(b)}`;}
function regionPage(id){if(id&&!['miyazaki','sea'].includes(id))return notFound();if(!id)return `<div class="wrap">${crumbs('ORIGINS')}<div class="page-head"><div class="eyebrow">ORIGINS</div><h1>おいしさには、<br>帰る場所がある。</h1><p>どこで、誰が、どうつくるのか。食卓から、産地へ。</p></div><div class="origin-catalog"><a href="#/region/miyazaki">${image('farm.png','塚田農場の契約農家の皆さん')}<small>MIYAZAKI / 地鶏</small><h2>宮崎。一羽を育てる日々。</h2><span class="text-link">産地の物語へ ${arrow}</span></a><a href="#/region/sea">${image('fish.jpg','産地から届く魚を使った四十八漁場の料理')}<small>JAPAN’S SEAS / 鮮魚</small><h2>全国の海。漁師から食卓へ。</h2><span class="text-link">海の物語へ ${arrow}</span></a></div></div>${actions()}`;const sea=id==='sea',b=brands[sea?1:0];return `<article><div class="wrap">${crumbs(`<a href="#/region">ORIGINS</a><span>/</span>${sea?'全国の海':'宮崎'}`)}<div class="article-head"><div class="eyebrow">${sea?'JAPAN’S SEAS':'MIYAZAKI'} / PRODUCERS & REGION</div><h1>${sea?'おいしさをつなぐ、<br>海の上の仕事。':'一羽を育てる日々が、<br>一皿につながっている。'}</h1>${badge}</div><figure class="article-hero">${image(sea?'fish.jpg':'farm.png',sea?'四十八漁場の刺身':'塚田農場の契約農家の皆さん','',true)}<figcaption>${sea?'四十八漁場の料理写真':'塚田農場公式サイト掲載の契約農家の皆さん。架空人物の記事とは異なります。'}</figcaption></figure></div><div class="article-body"><h2>${sea?'漁師と、漁協と、産地市場と。':'地鶏を育てる、という仕事。'}</h2><p>${sea?'四十八漁場は全国の漁師や漁協、産地市場と直接つながっています。水揚げ後の手当て、流通、調理。その道のりに関わることで、魚の価値を食卓へ届けています。':'塚田農場の地鶏は、親鳥づくりから始まります。ヒナを契約農家で育て、毎日の世話を重ねる。鶏が健やかに過ごす環境に目を配る生産者の仕事が、料理の土台をつくっています。'}</p>${!sea?`<figure>${image('chickens.png','土の上で育つ地鶏')}</figure>`:''}<h2>「仕入れる」の、もう一歩先へ。</h2><p>産地を知ることは、食材の背景を知ること。生産から食卓までをつなぐAPの生販直結は、つくり手の仕事を、お客様の体験へと受け渡していく仕組みです。</p>${sourceNote(sea?b.site:'https://www.tsukadanojo.jp/jidori/',b.name+'公式サイト')}${link('#/brand/'+b.id,'この産地とつながるブランドへ','solid-link')}</div></article>${related(b,'ORIGIN')}`;}
function peoplePage(){return `<div class="wrap">${crumbs('PEOPLE')}<div class="page-head"><div class="eyebrow">PEOPLE</div><h1>食の数だけ、<br>つくる人の想いがある。</h1><p>料理の背景にいる人を知る。仕事の話から、食の世界が広がる。</p><span class="demo-badge">人物・発言・経歴はすべて架空です。</span></div>${peopleFeature()}<div class="alumni"><span class="eyebrow">EDITORIAL SERIES / 企画サンプル</span><h2>AP、その後。</h2><p>食の現場で得た経験は、その先の人生にどうつながるのか。<br>退職後のキャリアを、多面的にたどるシリーズ企画。</p>${link('#/person/alumni','架空のストーリーを読む')}</div></div>${actions()}`;}
function personPage(id){if(!['naoto','alumni'].includes(id))return notFound();const alumni=id==='alumni';return `<article><div class="wrap">${crumbs(`<a href="#/people">PEOPLE</a><span>/</span>${alumni?'AP、その後。':'高橋直人'}`)}<div class="person-head"><div>${alumni?image('yakitori-b.jpg','焼鳥つかだの店内。人物の経歴とは関係のない参考写真','',true):image('fictional-chef.png','デモ用架空人物・高橋直人。AI生成画像','',true)}</div><div><div class="eyebrow">${alumni?'AP, AND BEYOND.':'PEOPLE / 料理をつくる人'}</div><h1>${alumni?'食の現場で学んだことを、<br>次の場所へ。':'おいしい理由を、<br>自分の言葉で。'}</h1><p>${alumni?'森 由佳 / 個人店の運営を想定':'高橋 直人 / 塚田農場の料理人を想定'}</p><span class="demo-badge">DEMO / 架空人物・架空の経歴</span><p class="small-note">${alumni?'写真は焼鳥つかだの店内参考写真で、この人物の店舗ではありません。':'顔写真はAI生成です。実在する社員ではありません。'}</p></div></div></div><div class="article-body"><p class="article-intro">${alumni?'これは、現場の経験を次の挑戦につなげる人物を想定した、デモ用のストーリーです。実際の退職者の経験や証言ではありません。':'産地で育まれた素材を、目の前のお客様へ。その間に立つ料理人の仕事を、架空の人物の視点から描きます。'}</p><h2>${alumni?'任される経験と、その難しさ。':'素材を知ると、料理が変わる。'}</h2><p>${alumni?'「売上だけでなく、仲間の働き方や、その日の食材のことも考える。ひとつの店には、想像よりずっと多くの仕事があるんだと知りました」。森は、日々の判断を重ねる難しさを語る人物として設定しています。':'「お客様に、なぜこの料理をおすすめするのか。自分が納得して伝えたいんです」。高橋は、料理の技術だけでなく、食材の背景にも関心を持つ料理人として設定しています。'}</p><h2>${alumni?'良かったことだけでは、語れない。':'産地から、食卓へ。自分の役割。'}</h2><p>${alumni?'「忙しさの中で、うまく伝えられなかったこともある。その反省は、今の店づくりに生きています」。経験を美談だけにせず、難しさも含めて振り返る。そんな人物企画を想定しています。':'「焼いて終わりではない。その一皿が届いたときに、どんな時間が生まれるかまで考えたい」。つくる人の仕事を受け取り、料理として仕上げる。そんな役割から、食に関わる仕事の広がりを描いています。'}</p><div class="fiction-note">人物名・発言・経験はすべてデモ用の創作です。実在社員・退職者の証言、待遇、キャリア実績を表すものではありません。</div>${link('#/story/'+(alumni?'brand':'jidori'),'食の物語へ')}${ext('https://career-recruit.ap-holdings.jp/','実際の仕事・採用情報を見る')}</div></article>${related(brands[0],'PEOPLE')}`;}
function storeCta(b){return `<section class="store-cta wrap"><div><span class="eyebrow">FROM STORY TO TABLE</span><h2>物語を知ったら、<br>次は、味わいに。</h2><p>${b.name}で、この食のつづきを。</p></div>${link('#/stores/'+b.id,'このブランドの店舗を探す','solid-link')}</section>`;}
function storesPage(id){const b=getBrand(id);if(id&&!b)return notFound();return `<div class="wrap">${crumbs('FIND A TABLE')}<div class="page-head"><div class="eyebrow">FIND A TABLE</div><h1>次の一皿を、<br>お店で。</h1><p>気になったブランドの公式サイトで、店舗・営業時間・空席をご確認ください。</p></div><div class="store-list">${(b?[b]:brands).map(b=>`<div><div class="store-thumb">${image(b.image,b.alt)}</div><div><small>${b.en}</small><h2>${b.name}</h2><p>${b.category}</p>${ext(b.store,b.id==='tsukada'?'公式の店舗検索・予約へ':'公式サイトで店舗・予約を見る','solid-link')}</div></div>`).join('')}</div><p class="small-note">公式サイトが別タブで開きます。このデモ内では予約は行われません。</p>${b?link('#/stores','他のブランドの店舗も見る'):ext('https://shop.ap-holdings.jp/','AP全体の店舗検索へ')}</div>${actions()}`;}
function diagnosisPage(){const q=questions[quizStep];return `<section class="quiz-page wrap">${crumbs('BRAND DISCOVERY')}<div class="quiz-layout"><aside><div class="eyebrow">FIND YOUR NEXT TABLE.</div><h1>今日の気分で、<br>店に出会う。</h1><p>考えすぎず、今の気持ちで。<br>3つの質問から、次に行きたいブランドを。</p><p class="small-note">お楽しみのブランド発見コンテンツです。<br>性格・採用適性を判定するものではありません。</p></aside><div class="quiz-panel"><div class="quiz-progress" aria-label="全3問のうち${quizStep+1}問目">${questions.map((_,i)=>`<span class="${i<=quizStep?'filled':''}"></span>`).join('')}</div><div class="quiz-counter">QUESTION <strong>0${quizStep+1}</strong> / 03</div><h2>${q.title}</h2><div class="quiz-options">${q.options.map((o,i)=>`<button data-answer="${i}" aria-pressed="${answers[quizStep]===i}"><small>0${i+1}</small>${o}<span>→</span></button>`).join('')}</div><div class="quiz-controls">${quizStep?'<button class="plain-button" data-quiz-back>← 前の質問</button>':'<span>所要時間：約30秒</span>'}<span>選ぶと${quizStep===2?'結果へ':'次の質問へ'}進みます</span></div></div></div></section>`;}
function recommendation(list){if(!Array.isArray(list)||list.length!==3||list.some(x=>!Number.isInteger(x)||x<0||x>2))throw Error('3つの回答を0〜2の整数で指定してください。');const scores=[0,0,0];list.forEach((x,i)=>scores[x]+=1);const high=Math.max(...scores);return brands[scores[list[1]]===high?list[1]:scores.indexOf(high)];}
function resultPage(id){const b=getBrand(id);if(!b)return notFound();return `<section class="result-page wrap">${crumbs('YOUR NEXT TABLE')}<div class="result-head"><div class="eyebrow">YOUR NEXT TABLE / 今日のおすすめ</div><h1>今のあなたに、${b.name}。</h1><p>今日の気分から見つけた、次の食の時間。</p></div><div class="result-layout"><div>${image(b.image,b.alt,'',true)}</div><div><small>${b.en}</small><h2>${b.tag}</h2><p>${b.reason}</p>${link('#/brand/'+b.id,'ブランドの世界を見に行く','solid-link')}${link('#/food/'+b.id,'まずは、料理から知る')}<button class="plain-button" data-restart>もう一度、見つける ↺</button></div></div><p class="small-note">気分と好みをもとにした、お楽しみのおすすめです。回答は保存しません。</p></section>${related(b)}${storeCta(b)}`;}
function aboutPage(){return `<div class="wrap">${crumbs('ABOUT')}<div class="page-head"><div class="eyebrow">WE ARE A FOOD CREATIVE FIRM.</div><h1>食のあるべき姿を<br>追求する。</h1><p>APホールディングスの既存のMissionを、このメディアの中心に。</p></div><div class="article-body about-body"><h2>産地と食卓を、つなぐ。</h2><p>APは生産・加工・流通・販売に関わる「生販直結」の仕組みを展開しています。店や料理の背景にある仕事まで見つめると、APという会社の輪郭が見えてきます。</p><div class="connection-strip">${['産地','料理','ブランド','人','未来'].map((s,i)=>link(['#/region','#/food/tsukada','#/brands','#/people','#/story/future'][i],s)).join('')}</div><h2>食の未来を広げていく。</h2><p>FOOD CREATIVE FIRM。食に関わる多様な活動から未来の可能性を広げていくというAPのビジョンです。</p><h2>このメディアの編集テーマ</h2><p>食をつくる。産地とつくる。店をつくる。人とつくる。未来をつくる。「つくる」は、APの活動をたどるための編集上の言葉です。企業理念を新しく定義するものではありません。</p>${sourceNote('https://ap-holdings.jp/mission/','APホールディングス「私たちの使命」')}${link('#/sources','出典とデモの前提を見る')}</div></div>${actions()}`;}
function sourcesPage(){return `<div class="wrap">${crumbs('SOURCES & DEMO')}<div class="page-head"><div class="eyebrow">SOURCES & DEMO</div><h1>出典と、<br>このデモについて。</h1></div><div class="article-body about-body"><h2>営業提案用の非公式デモです。</h2><p>AP JOURNALという名称、編集コピー、記事、レイアウトは提案用です。APホールディングスの公式メディアではありません。既存のMission・Vision・ブランド情報は以下の公式公開情報を参照しています。</p><h2>公開情報の参照先</h2><ul class="source-list">${[['https://ap-holdings.jp/mission/','APホールディングス｜私たちの使命'],['https://ap-holdings.jp/business-model/','APホールディングス｜ビジネスモデル'],['https://ap-holdings.jp/brand-and-business/','APホールディングス｜ブランド＆ビジネス'],['https://www.tsukadanojo.jp/kodawari/','塚田農場｜こだわり（炎・地鶏・契約農家の写真）'],['https://www.tsukadanojo.jp/jidori/','塚田農場｜地鶏（飼育風景）'],['https://www.48gyojyou.com/','四十八漁場（料理写真）'],['https://ap-holdings.jp/brand-and-business/焼鳥つかだ中目黒/','焼鳥つかだ（調理・仕込み・店内写真）']].map(([u,t])=>`<li>${ext(u,t)}</li>`).join('')}</ul><h2>人物と記事</h2><p>高橋直人・森由佳は架空人物です。人物の発言・経歴・経験は創作で、実在の社員・退職者のものではありません。高橋直人の顔写真はAI生成画像です。その他は公式サイト掲載の実写素材で、架空人物の本人写真としては使用していません。</p><h2>写真・ブランドの権利</h2><p>公式写真・商標等の権利は各権利者に帰属します。オープンライセンスは確認できていません。本デモは非公開の提案用として扱い、一般公開・本番利用時は使用許諾や素材差し替えを確認してください。</p><h2>実装範囲</h2><p>記事から料理・産地・ブランド・店舗への回遊、3問のブランド発見体験、3ブランドの結果と詳細ページを体験できます。予約・採用・問い合わせは公式サイトへ接続します。CMS、予約API、応募受付は含みません。</p><p class="small-note">参照確認日：2026年9月23日。最新情報は各公式サイトをご確認ください。</p></div></div>`;}
function notFound(){return `<section class="wrap page-head"><div class="eyebrow">PAGE NOT FOUND</div><h1>このページは見つかりません。</h1>${link('#/','トップへ戻る','solid-link')}</section>`;}
function render(){const [type,id]=(location.hash.slice(1)||'/').split('/').filter(Boolean);let html,title='食の、その先へ。';switch(type){case undefined:html=home();break;case 'stories':html=storiesPage(id||'all');title='STORIES';break;case 'story':html=article(id);title=getStory(id)?.title||'STORY';break;case 'brands':html=brandsPage();title='BRANDS';break;case 'brand':html=brandPage(id);title=getBrand(id)?.name||'BRAND';break;case 'food':html=foodPage(id);title=getBrand(id)?.food||'FOOD';break;case 'region':html=regionPage(id);title='ORIGINS';break;case 'people':html=peoplePage();title='PEOPLE';break;case 'person':html=personPage(id);title=id==='alumni'?'AP、その後。':'高橋直人の物語';break;case 'stores':html=storesPage(id);title='店舗を探す';break;case 'diagnosis':html=diagnosisPage();title='今日の気分で、店に出会う';break;case 'result':html=resultPage(id);title='今日のおすすめ';break;case 'about':html=aboutPage();title='ABOUT';break;case 'sources':html=sourcesPage();title='出典とデモについて';break;default:html=notFound();}main.innerHTML=html;document.title=`${title} | AP JOURNAL`;document.querySelector('header').classList.remove('menu-open');document.querySelector('.menu-toggle').setAttribute('aria-expanded','false');document.querySelectorAll('nav a').forEach(a=>a.toggleAttribute('aria-current',a.hash.split('/')[1]===type));window.scrollTo({top:0,behavior:'instant'});main.focus({preventScroll:true});setupMotion();}
document.querySelector('.menu-toggle').addEventListener('click',()=>{const open=document.querySelector('header').classList.toggle('menu-open');document.querySelector('.menu-toggle').setAttribute('aria-expanded',String(open));});
document.addEventListener('click',e=>{if(e.target.closest('.skip')){e.preventDefault();main.focus();return;}const tab=e.target.closest('[data-brand]');if(tab){activeBrand=tab.dataset.brand;document.querySelectorAll('[data-brand]').forEach(t=>{t.setAttribute('aria-selected',String(t===tab));t.tabIndex=t===tab?0:-1;});const p=document.getElementById('brand-panel');p.innerHTML=brandPanel(activeBrand);p.setAttribute('aria-labelledby',tab.id);p.classList.remove('panel-enter');void p.offsetWidth;p.classList.add('panel-enter');}const scroll=e.target.closest('[data-scroll]');if(scroll){e.preventDefault();document.getElementById(scroll.dataset.scroll)?.scrollIntoView({behavior:reducedMotion.matches?'instant':'smooth'});}const journey=e.target.closest('[data-journey]');if(journey){if(reducedMotion.matches){showJourney(Number(journey.dataset.journey));return;}const el=document.querySelector('.journey'),height=el.offsetHeight-document.querySelector('.journey-sticky').offsetHeight;window.scrollTo({top:el.offsetTop-84+height*(Number(journey.dataset.journey)/3+.13),behavior:reducedMotion.matches?'instant':'smooth'});}const answer=e.target.closest('[data-answer]');if(answer){answers[quizStep]=Number(answer.dataset.answer);if(quizStep<2){quizStep++;render();}else location.hash='/result/'+recommendation(answers).id;}if(e.target.closest('[data-quiz-back]')){quizStep=Math.max(0,quizStep-1);render();}if(e.target.closest('[data-restart]')){answers=[];quizStep=0;location.hash='/diagnosis';}if(e.target.closest('a[href="#/diagnosis"]')){answers=[];quizStep=0;if(location.hash==='#/diagnosis')render();}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.querySelector('header').classList.remove('menu-open');document.querySelector('.menu-toggle').setAttribute('aria-expanded','false');}const tab=e.target.closest('[data-brand]');if(!tab||!['ArrowDown','ArrowUp','ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const tabs=[...document.querySelectorAll('[data-brand]')],i=tabs.indexOf(tab),next=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(['ArrowDown','ArrowRight'].includes(e.key)?1:-1)+tabs.length)%tabs.length;tabs[next].click();tabs[next].focus();});
const reducedMotion=matchMedia('(prefers-reduced-motion: reduce)');let observer,frame=0,currentJourney=-1;
function setupMotion(){observer?.disconnect();currentJourney=-1;document.body.classList.add('motion-ready');observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('in-view');observer.unobserve(e.target);}}),{threshold:.08});document.querySelectorAll('.reveal').forEach(el=>observer.observe(el));updateMotion();}
const journeyText=[['炎の先に、<br>つくる人の手。','炭と炎を見極める。その一瞬に、料理人の仕事がある。'],['一皿の先に、<br>広がる食の時間。','料理を囲み、語り合う。食が、人と人をつないでいく。'],['そのおいしさは、<br>この土地から。','食卓から産地へ。地鶏を育てる人たちと、ひとつにつながる。']];
function showJourney(index){const journey=document.querySelector('.journey');if(!journey)return;currentJourney=index;journey.querySelectorAll('.journey-image').forEach((img,i)=>img.classList.toggle('active',i===index));journey.querySelector('.journey-number').textContent='0'+(index+1);journey.querySelector('h2').innerHTML=journeyText[index][0];journey.querySelector('.journey-copy p').textContent=journeyText[index][1];journey.querySelectorAll('[data-journey]').forEach((b,i)=>b.setAttribute('aria-pressed',String(i===index)));}
function updateMotion(){frame=0;const hero=document.querySelector('.hero-photo');if(hero&&!reducedMotion.matches)hero.style.transform=`scale(${1.04+Math.min(scrollY/innerHeight,.7)*.08}) translateY(${Math.min(scrollY*.13,100)}px)`;const journey=document.querySelector('.journey');if(!journey)return;if(reducedMotion.matches){if(currentJourney<0)showJourney(0);return;}const sticky=journey.querySelector('.journey-sticky'),top=parseFloat(getComputedStyle(sticky).top)||84,p=Math.max(0,Math.min(1,(top-journey.getBoundingClientRect().top)/(journey.offsetHeight-sticky.offsetHeight)));const index=Math.min(2,Math.floor(p*3));journey.querySelector('.journey-progress span').style.transform=`scaleX(${p})`;if(currentJourney!==index)showJourney(index);journey.querySelector('.journey-image.active').style.transform=`scale(${1.08-(p*3%1)*.07})`;}
window.addEventListener('scroll',()=>{if(!frame)frame=requestAnimationFrame(updateMotion);},{passive:true});window.addEventListener('hashchange',render);render();
if(document.modelContext?.registerTool){const lifecycle=new AbortController();try{Promise.resolve(document.modelContext.registerTool({name:'discover_ap_brand',title:'気分に合うAPブランドを見つける',description:'3問への回答を反映し、画面にブランド発見の結果を表示します。予約は行いません。',inputSchema:{type:'object',properties:{answers:{type:'array',items:{type:'integer',minimum:0,maximum:2},minItems:3,maxItems:3}},required:['answers'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:async input=>{const b=recommendation(input?.answers);answers=[...input.answers];quizStep=2;history.pushState(null,'','#/result/'+b.id);render();return{brand:b.name,route:'#/result/'+b.id};}},{signal:lifecycle.signal})).catch(()=>{});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}catch{}}
